14	// V2: Invalidates cache, re-evaluates booking visibility, and dispatches Square/Fresha sync on service changes.
15	class ServiceObserver
16	{
17	    public bool $afterCommit = true;
18	
19	    public function __construct(
20	        private readonly ProfessionalCacheService $professionalCache,
21	        private readonly SectionVisibilityService $visibilityService,
22	    ) {}
23	
24	    private function bust(Service $service): ?Professional
25	    {
26	        // Eager-load site once — every downstream caller (reevaluateBooking,
27	        // shouldDispatchSquareSync, shouldDispatchFreshaSync) reads $pro->site.
28	        $pro = Professional::query()->with('site')->find($service->professional_id);
29	
30	        try {
31	            if ($pro) {
32	                $this->professionalCache->invalidateProfessional($pro);
33	            }
34	        } catch (\Throwable $e) {
35	            Log::warning('Professional cache invalidation failed on service change', [
36	                'service_id' => $service->id,
37	                'professional_id' => $service->professional_id,
38	                'message' => $e->getMessage(),
39	            ]);
40	        }
41	
42	        return $pro;
43	    }
44	
45	    public function saved(Service $service): void
46	    {
47	        $this->runHooks($service, 'upsert');
48	    }
49	
