3	namespace App\Observers\Core;
4	
5	use App\Jobs\Fresha\PushServiceToFreshaJob;
6	use App\Jobs\Square\PushServiceToSquareJob;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use App\Models\Core\Professional\Service;
10	use App\Services\Cache\ProfessionalCacheService;
11	use App\Services\Professional\SectionVisibilityService;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Invalidates cache, re-evaluates booking visibility, and dispatches Square/Fresha sync on service changes.
15	class ServiceObserver
16	{
17	    public bool $afterCommit = true;
18	
19	    public function __construct(
20	        private readonly ProfessionalCacheService $professionalCache,
21	        private readonly SectionVisibilityService $visibilityService,
22	    ) {}
23	
24	    private function bust(Service $service): ?Professional
25	    {
26	        // Eager-load site once — every downstream caller (reevaluateBooking,
27	        // shouldDispatchSquareSync, shouldDispatchFreshaSync) reads $pro->site.
28	        // DB query has its own catch so a connection error returns null (pipeline
29	        // continues) rather than propagating to the outer runHooks catch-all.
30	        $pro = null;
31	        try {
32	            $pro = Professional::query()->with('site')->find($service->professional_id);
33	        } catch (\Throwable $e) {
34	            Log::warning('Professional lookup failed during cache bust', [
35	                'service_id' => $service->id,
36	                'professional_id' => $service->professional_id,
37	                'message' => $e->getMessage(),
38	            ]);
39	
40	            return null;
41	        }
42	
43	        try {
44	            if ($pro) {
45	                $this->professionalCache->invalidateProfessional($pro);
46	            }
47	        } catch (\Throwable $e) {
48	            Log::warning('Professional cache invalidation failed on service change', [
49	                'service_id' => $service->id,
50	                'professional_id' => $service->professional_id,
51	                'message' => $e->getMessage(),
52	            ]);
53	        }
54	
55	        return $pro;
56	    }
57	
58	    public function saved(Service $service): void
59	    {
60	        $this->runHooks($service, 'upsert');
61	    }
62	
63	    public function deleted(Service $service): void
64	    {
65	        $this->runHooks($service, 'delete');
66	    }
67	
68	    public function restored(Service $service): void
69	    {
70	        $this->runHooks($service, 'upsert');
71	    }
72	
73	    /**
74	     * Side-effect runner. Wraps every step in its own try/catch + a
75	     * top-level catch-all so an observer failure can never bubble up
76	     * and turn the originating Service::save() into a 500. Logs every
77	     * failure with the service id for triage.
78	     */
79	    private function runHooks(Service $service, string $action): void
80	    {
81	        try {
82	            $pro = $this->bust($service);
83	            $this->reevaluateBooking($service, $pro);
84	
85	            if ($this->shouldDispatchSquareSync($pro)) {
86	                $this->dispatchSquareSync($service->id, $action);
87	            }
88	
89	            if ($this->shouldDispatchFreshaSync($pro)) {
90	                $this->dispatchFreshaSync($service->id, $action);
91	            }
92	        } catch (\Throwable $e) {
93	            // Catch-all so a sync/cache/visibility failure can't trip the
94	            // request. Each step has its own try/catch; this wraps the
95	            // glue + any unanticipated error in helper resolution.
96	            Log::error('ServiceObserver hook failed', [
97	                'service_id' => $service->id,
98	                'professional_id' => $service->professional_id,
99	                'action' => $action,
100	                'message' => $e->getMessage(),
101	                'trace' => $e->getTraceAsString(),
102	            ]);
103	        }
104	    }
105	
106	    private function reevaluateBooking(Service $service, ?Professional $pro): void
107	    {
108	        try {
109	            $site = $pro?->site;
110	            if (! $site) {
111	                return;
112	            }
113	
114	            // Both sections gate on "has at least one valid service": booking
115	            // requires it for the booking link/integration check, services
116	            // requires it directly. Re-evaluate both so is_enabled tracks
117	            // reality after add/update/delete/restore.
118	            foreach (['booking', 'services'] as $blockType) {
119	                $this->visibilityService->reevaluateEnabled(
120	                    (string) $service->professional_id,
121	                    (string) $site->id,
122	                    $blockType,
123	                );
124	            }
125	        } catch (\Throwable $e) {
126	            Log::warning('Section visibility reevaluation failed on service change', [
127	                'service_id' => $service->id,
128	                'professional_id' => $service->professional_id,
129	                'message' => $e->getMessage(),
130	            ]);
131	        }
132	    }
133	
134	    private function dispatchSquareSync(string $serviceId, string $action): void
135	    {
136	        try {
137	            // Queued on the 'integrations' queue (Horizon required for syncs to process).
138	            PushServiceToSquareJob::dispatch($serviceId, $action);
139	        } catch (\Throwable $e) {
140	            // Never fail core service CRUD because sync dispatch failed.
141	            Log::warning('PushServiceToSquareJob dispatch failed', [
142	                'service_id' => $serviceId,
143	                'action' => $action,
144	                'message' => $e->getMessage(),
145	            ]);
146	        }
147	    }
148	
149	    private function dispatchFreshaSync(string $serviceId, string $action): void
150	    {
151	        try {
152	            // Queued on the 'integrations' queue (Horizon required for syncs to process).
153	            PushServiceToFreshaJob::dispatch($serviceId, $action);
154	        } catch (\Throwable $e) {
155	            // Never fail core service CRUD because sync dispatch failed.
156	            Log::warning('PushServiceToFreshaJob dispatch failed', [
157	                'service_id' => $serviceId,
158	                'action' => $action,
159	                'message' => $e->getMessage(),
160	            ]);
161	        }
162	    }
163	
164	    private function shouldDispatchSquareSync(?Professional $professional): bool
165	    {
166	        if (! (bool) config('sidest.features.square_sync', false)) {
167	            return false;
168	        }
169	
170	        if (! $professional) {
171	            return false;
172	        }
173	
174	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
175	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
176	            return false;
177	        }
178	
179	        return (bool) data_get($professional->site?->settings, 'services_auto_sync_enabled', false);
180	    }
181	
182	    private function shouldDispatchFreshaSync(?Professional $professional): bool
183	    {
184	        if (! (bool) config('sidest.features.fresha_sync', false)) {
185	            return false;
186	        }
187	
188	        if (! $professional) {
189	            return false;
190	        }
191	
192	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_FRESHA);
193	        if (! $integration || empty($integration->access_token) || empty($integration->external_account_id)) {
194	            return false;
195	        }
196	
197	        return (bool) data_get($professional->site?->settings, 'services_auto_sync_enabled', false);
198	    }
199	}
