10	function invokePrivateObserverMethod(string $method, Professional $pro): bool
11	{
12	    $observer = app(ServiceObserver::class);
13	    $reflection = new ReflectionClass($observer);
14	    $reflectionMethod = $reflection->getMethod($method);
15	    $reflectionMethod->setAccessible(true);
16	
17	    return (bool) $reflectionMethod->invoke($observer, $pro);
18	}
19	
20	function invokeDispatchMethod(string $method, string $serviceId, string $action): void
21	{
22	    $observer = app(ServiceObserver::class);
23	    $reflection = new ReflectionClass($observer);
24	    $reflectionMethod = $reflection->getMethod($method);
25	    $reflectionMethod->setAccessible(true);
26	    $reflectionMethod->invoke($observer, $serviceId, $action);
27	}
28	
29	it('shouldDispatchSquareSync returns false when square_sync flag is off', function () {
30	    config()->set('sidest.features.square_sync', false);
31	
32	    $pro = new Professional(['id' => 'pro-anything']);
33	
34	    expect(invokePrivateObserverMethod('shouldDispatchSquareSync', $pro))->toBeFalse();
35	});
36	
37	it('shouldDispatchFreshaSync returns false when fresha_sync flag is off', function () {
38	    config()->set('sidest.features.fresha_sync', false);
39	
40	    $pro = new Professional(['id' => 'pro-anything']);
41	
42	    expect(invokePrivateObserverMethod('shouldDispatchFreshaSync', $pro))->toBeFalse();
43	});
44	
45	// CR-006: dispatch() queues jobs rather than blocking the HTTP response synchronously.
46	it('dispatchSquareSync queues PushServiceToSquareJob', function () {
47	    Queue::fake();
48	
49	    invokeDispatchMethod('dispatchSquareSync', 'svc-123', 'upsert');
50	
51	    Queue::assertPushed(PushServiceToSquareJob::class, function ($job) {
52	        return $job->serviceId === 'svc-123' && $job->action === 'upsert';
53	    });
54	});
55	
56	it('dispatchFreshaSync queues PushServiceToFreshaJob', function () {
57	    Queue::fake();
58	
59	    invokeDispatchMethod('dispatchFreshaSync', 'svc-456', 'delete');
60	
61	    Queue::assertPushed(PushServiceToFreshaJob::class, function ($job) {
62	        return $job->serviceId === 'svc-456' && $job->action === 'delete';
63	    });
64	});
65	
66	// CR-005: bust() failure must not abort the rest of the runHooks pipeline.
67	// A service whose professional doesn't exist causes bust() to return null.
68	// The pipeline should complete without exception and dispatch no sync jobs.
69	it('runHooks completes without exception when professional is not found', function () {
70	    Queue::fake();
71	
72	    $service = new Service([
73	        'id' => 'svc-orphan',
74	        'professional_id' => '00000000-0000-0000-0000-000000000000',
75	    ]);
76	
77	    $observer = app(ServiceObserver::class);
78	    $reflection = new ReflectionClass($observer);
79	    $method = $reflection->getMethod('runHooks');
80	    $method->setAccessible(true);
81	
82	    // Should not throw — bust() returns null, downstream steps skip gracefully.
83	    $method->invoke($observer, $service, 'upsert');
84	
85	    Queue::assertNothingPushed();
86	});
